/// <summary>
///     Data Controller class for <c>AVAsmmActivitiesWeeklyPlanADMReport</c> SSRS report
/// </summary>
/// <remarks>
///     This is the Controller class for the <c>AVAsmmActivitiesWeeklyPlanADMReport</c> SSRS Report.
/// </remarks>
internal final class AVAsmmActivitiesWeeklyPlanADMReportController extends  SrsReportRunController
{
    Args                        clsArgs;
    smmActivities               clsSmmActivities;
    smmBusRelTable              clsSmmBusRelTable;
    CustTable                   clsCustTable;
    boolean                     clsPreviewMode;

}

Method.Source:
/// <summary>
///    AVA <c>construct</c> method.
/// </summary>
/// <returns>
///    <c>AVAsmmActivitiesWeeklyPlanADMReportController</c> as return value
/// </returns>
public static AVAsmmActivitiesWeeklyPlanADMReportController construct()
{
    return new AVAsmmActivitiesWeeklyPlanADMReportController();
}

/// <summary>
///    AVA <c>parmArgs</c> method.
/// </summary>
/// <param name="_parmValue">
///    <c>RefRecId</c> as type
/// </param>
/// <returns>
///    <c>Args</c> as return value
/// </returns>
public Args parmArgs(Args _parmValue = clsArgs)
{
    clsArgs = _parmValue;

    return clsArgs;
}

/// <summary>
///    AVA <c>parmSmmActivities</c> method.
/// </summary>
/// <param name="_parmValue">
///    <c>smmActivities</c> as type
/// </param>
/// <returns>
///    <c>smmActivities</c> as return value
/// </returns>
public smmActivities parmSmmActivities(smmActivities _parmValue = clsSmmActivities)
{
    clsSmmActivities = _parmValue;

    return clsSmmActivities;
}

/// <summary>
///    AVA <c>parmCustTable</c> method.
/// </summary>
/// <param name="_parmValue">
///    <c>CustTable</c> as type
/// </param>
/// <returns>
///    <c>CustTable</c> as return value
/// </returns>
public CustTable parmCustTable(CustTable _parmValue = clsCustTable)
{
    clsCustTable = _parmValue;

    return clsCustTable;
}

/// <summary>
///    AVA <c>parmSmmBusRelTable</c> method.
/// </summary>
/// <param name="_parmValue">
///    <c>smmBusRelTable</c> as type
/// </param>
/// <returns>
///    <c>smmBusRelTable</c> as return value
/// </returns>
public smmBusRelTable parmSmmBusRelTable(smmBusRelTable _parmValue = clssmmBusRelTable)
{
    clsSmmBusRelTable = _parmValue;

    return clsSmmBusRelTable;
}

/// <summary>
///    AVA <c>main</c> method.
/// </summary>
/// <param name="_args">
///    <c>Args</c> as type
/// </param>
public static void main(Args _args)
{
    AVAsmmActivitiesWeeklyPlanADMReportController controller;

    controller = AVAsmmActivitiesWeeklyPlanADMReportController::newFromArgs(_args);

    controller.parmReportName(ssrsReportStr(AVAsmmActivitiesWeeklyPlanADMReport, Report));
    controller.parmDialogCaption("@NDX:NXAADMWeeklyPlan");
    controller.startOperation();
}

/// <summary>
///    AVA <c>prePromptModifyContract</c> method.
/// </summary>
protected void prePromptModifyContract()
{
    AVAsmmActivitiesWeeklyPlanADMReportContract contract;

    date                                        locToday;
    int                                         locTodayDayOfWeek;
    TimeZone                                    locTimeZone;

    clsPreviewMode  = false;

    contract        = this.parmReportContract().parmRdpContract();

    contract.parmSmmActivityNumber(clsSmmActivities.ActivityNumber);

    contract.parmPrintMode(SalesTableMode::Simple);

    locTimeZone                         = DateTimeUtil::getUserPreferredTimeZone();
    locToday                            = DateTimeUtil::getToday(locTimeZone);
    locTodayDayOfWeek                   = dayofwk(locToday);
    if(locTodayDayOfWeek == 1)
    {
        contract.parmEvaluationDateFrom(locToday);
    }
    else
    {
        contract.parmEvaluationDateFrom(locToday - (locTodayDayOfWeek - 1));
    }
    contract.parmEvaluationDateTo(contract.parmEvaluationDateFrom() + (7 - 1));

    // Set the target print destination to Screen if we are previewing the report.
    if(this.parmArgs())
    {
        if(this.parmArgs().menuItemName() == menuItemActionStr(AVAsmmActivitiesWeeklyPlanADMReportActionPreview))
        {
            clsPreviewMode = true;
        }
        else if(this.parmArgs().menuItemName() == menuItemActionStr(AVAsmmActivitiesWeeklyPlanADMReportAction))
        {
            clsPreviewMode = false;
        }
    }

    if (clsPreviewMode)
    {
        this.parmReportContract().parmPrintSettings().printMediumType(SRSPrintMediumType::Screen);
    }

    // Don't show the report dialog if Preview
    // and don't save to SysLastValue either.
    this.parmShowDialog(!clsPreviewMode);
    this.parmLoadFromSysLastValue(!clsPreviewMode);
}

/// <summary>
///    AVA <c>newFromArgs</c> method.
/// </summary>
/// <param name="_args">
///    <c>Args</c> as type
/// </param>
/// <returns>
///    <c>AVAsmmActivitiesWeeklyPlanADMReportController</c> as return value
/// </returns>
public static AVAsmmActivitiesWeeklyPlanADMReportController newFromArgs(Args _args)
{
    AVAsmmActivitiesWeeklyPlanADMReportController   locController;
    Common                                          locCommon;
    smmActivities                                   locsmmActivities;
    smmBusRelTable                                  locsmmBusRelTable;
    CustTable                                       locCustTable;

    //locController = new AVAsmmActivitiesWeeklyPlanADMReportController();
    locController = AVAsmmActivitiesWeeklyPlanADMReportController::construct();
    locController.parmArgs(_args);
    locController.parmLoadFromSysLastValue(false);

    if(_args)
    {
        if(_args.record().RecId)
        {
            locCommon = _args.record();

            switch(locCommon.TableId)
            {
                case tableNum(smmActivities):
                    locsmmActivities = locCommon;
                    locController.parmSmmActivities(locsmmActivities);
                    break;

                case tableNum(smmBusRelTable):
                    locsmmBusRelTable = locCommon;
                    locController.parmSmmBusRelTable(locsmmBusRelTable);
                    break;

                case tableNum(CustTable):
                    locCustTable = locCommon;
                    locController.parmCustTable(locCustTable);
                    break;

                default:
                    locController.parmLoadFromSysLastValue(true);
            }
        }
        else
        {
            locController.parmLoadFromSysLastValue(true);
        }
    }
    return locController;
}
